/// setter for IN DataPort
pub fn put_AttackStatusRx(value: SW::AttackStatus)
{
  *extern_api::IN_AttackStatusRx.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_AttackStatusTx(value: SW::AttackStatus)
{
  *extern_api::IN_AttackStatusTx.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_CurrentMode() -> SW::Mode
{
  return extern_api::OUT_CurrentMode.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for GUMBO State Variable
pub fn get_currentMode() -> SW::Mode
{
  unsafe {
    match &crate::app {
      Some(inner) => inner.currentMode,
      None => panic!("The app is None")
    }
  }
}

/// setter for GUMBO State Variable
pub fn put_currentMode(value: SW::Mode)
{
  unsafe {
    match &mut crate::app {
      Some(inner) => inner.currentMode = value,
      None => panic!("The app is None")
    }
  }
}

